using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool that fetches data from an external HTTP API.
/// HttpClient is injected via DI (registered as a typed/named client in Program.cs).
/// </summary>
internal class ApiFetchTool(HttpClient httpClient, ILogger<ApiFetchTool> logger)
{
    [McpServerTool]
    [Description("Fetches JSON data from an external API at the given URL and returns the response body.")]
    public async Task<string> FetchApi(
        [Description("The absolute URL to fetch (e.g. https://api.example.com/data)")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching URL: {Url}", url);

        using var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadAsStringAsync(cancellationToken);

        // Return pretty-printed JSON when possible; fall back to raw text.
        try
        {
            var doc = JsonDocument.Parse(body);
            return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (JsonException)
        {
            return body;
        }
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

/// <summary>
/// Prompt templates exposed to MCP clients.
/// </summary>
internal class SummarizationPrompts
{
    [McpServerPrompt]
    [Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static ChatMessage Summarize(
        [Description("The text to summarize")] string text,
        [Description("Desired summary style (e.g. brief, detailed, bullet-points)")] string style = "brief")
    {
        return new ChatMessage(
            ChatRole.User,
            $"Summarize the following text in a {style} style:\n\n{text}");
    }
}

