using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

/// <summary>
/// Prompt templates exposed to MCP clients.
/// </summary>
internal class SummarizationPrompts
{
    [McpServerPrompt]
    [Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static PromptMessage Summarize(
        [Description("The text to summarize")] string text,
        [Description("Desired summary style (e.g. brief, detailed, bullet-points)")] string style = "brief")
    {
        return new PromptMessage
        {
            Role = Role.User,
            Content = new TextContentBlock
            {
                Text = $"Summarize the following text in a {style} style:\n\n{text}"
            }
        };
    }
}

